// Negative control (mutate.mjs needs polynv, absent here): write hand-seeded mutants of the
// spec to spec/out/<name>/m.cjs; each must flip replay windows and/or break an invariant.
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';

const src = readFileSync(new URL('./run.spec.cjs', import.meta.url), 'utf8');
const MUTANTS = {
  'abort-all': ["model.abort0 || model.task0 === 'assigned'", 'true'],
