test('first failure retries; second failure is recorded; failed only once both reported', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'running', task0: 'assigned', task1: 'assigned', retried0: false, retried1: true });
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  await h.workFailed('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'running', task0: 'assigned', task1: 'failed', retried0: false, retried1: true });
  await h.workDone('worker0');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'completed', task1: 'failed', retried0: false, retried1: true });
});

test('retry sends Assign from the run to the worker', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker0');
  const [rep] = await h.inFlight();
  await h.deliver(rep.id);
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 1);
  assert.deepEqual({ from: msgs[0].from, to: msgs[0].to, action: msgs[0].action, data: msgs[0].data },
    { from: 'run', to: 'worker0', action: 'Assign', data: {} });
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  await h.deliverAll();
  await h.workDone('worker0');
  await h.workDone('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed', retried0: true, retried1: false });
});

test('failure while cancelling is recorded, not retried', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker0');
  await h.workDone('worker1');
  await h.cancel();
  // Deliver only the reports: Aborts reach idle workers later and are ignored.
  for (const m of (await h.inFlight()).filter((m) => m.action === 'Report')) await h.deliver(m.id);
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'failed', task1: 'completed', retried0: false, retried1: false });
  await h.deliverAll();
  assert.deepEqual(await h.inFlight(), []);
});

test('cancel during a retry aborts the retried task', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker0');
  await h.deliverAll(); // retry Assign delivered, worker0 busy again
  assert.deepEqual(await h.cancel(), { ok: true });
  assert.equal((await h.inFlight()).filter((m) => m.action === 'Abort').length, 2);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'cancelled', task0: 'cancelled', task1: 'cancelled', retried0: true, retried1: false });
});

