'use strict';
// SAM v2 strict-profile model of src/core.ts + the network in src/host.impl.ts.
// One step = one command or one message delivery. In-flight messages are flags:
// each worker gets at most one Assign, one Abort and one Report per run.

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const INITIAL_STATE = {
  status: 'idle',
  task0: 'idle', task1: 'idle',
  w0: 'idle', w1: 'idle',
  assign0: false, assign1: false,
  abort0: false, abort1: false,
  report0: 'none', report1: 'none',
};

const KEYS = Object.keys(INITIAL_STATE);
const others = (...written) => KEYS.filter((k) => !written.includes(k));
const W = [{ worker: 0 }, { worker: 1 }];
const T = [{ task: 0 }, { task: 1 }];
const live = (s) => s === 'running' || s === 'cancelling';

function finish(outcome) {
  return (model) => (p, { reject, next, unchanged }) => {
    const i = p.worker;
    if (i !== 0 && i !== 1) return reject('unknown-worker');
    if (model[`w${i}`] !== 'busy') return reject('worker-not-busy');
    next[`w${i}`] = 'idle';
    next[`report${i}`] = outcome;
    unchanged(...others(`w${i}`, `report${i}`));
  };
}

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      status: { type: 'string' },
      task0: { type: 'string' }, task1: { type: 'string' },
      w0: { type: 'string' }, w1: { type: 'string' },
      assign0: { type: 'boolean' }, assign1: { type: 'boolean' },
      abort0: { type: 'boolean' }, abort1: { type: 'boolean' },
      report0: { type: 'string' }, report1: { type: 'string' },
    },
    actions: {
      START: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      CANCEL: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      WORK_DONE: { action: (data = {}) => ({ ...data }), schema: { worker: 'number' }, domain: W },
      WORK_FAILED: { action: (data = {}) => ({ ...data }), schema: { worker: 'number' }, domain: W },
      DELIVER_ASSIGN: { action: (data = {}) => ({ ...data }), schema: { worker: 'number' }, domain: W },
      DELIVER_ABORT: { action: (data = {}) => ({ ...data }), schema: { worker: 'number' }, domain: W },
      DELIVER_REPORT: { action: (data = {}) => ({ ...data }), schema: { task: 'number' }, domain: T },
    },
    acceptors: {
      START: (model) => (p, { reject, next, unchanged }) => {
        if (model.status !== 'idle') return reject('already-started');
        next.status = 'running';
        next.task0 = 'assigned';
        next.task1 = 'assigned';
        next.assign0 = true;
        next.assign1 = true;
        unchanged(...others('status', 'task0', 'task1', 'assign0', 'assign1'));
      },
      CANCEL: (model) => (p, { reject, next, unchanged }) => {
        if (model.status !== 'running') return reject('not-running');
        next.status = 'cancelling';
        next.abort0 = model.abort0 || model.task0 === 'assigned';
        next.abort1 = model.abort1 || model.task1 === 'assigned';
        unchanged(...others('status', 'abort0', 'abort1'));
      },
      WORK_DONE: finish('completed'),
      WORK_FAILED: finish('failed'),
      DELIVER_ASSIGN: (model) => (p, { reject, next, unchanged }) => {
        const i = p.worker;
        if (i !== 0 && i !== 1) return reject('unknown-worker');
        if (!model[`assign${i}`]) return reject('no-assign-in-flight');
        next[`assign${i}`] = false;
        if (model[`w${i}`] === 'idle') {
          next[`w${i}`] = 'busy';
          unchanged(...others(`assign${i}`, `w${i}`));
        } else {
          unchanged(...others(`assign${i}`));
        }
      },
      DELIVER_ABORT: (model) => (p, { reject, next, unchanged }) => {
        const i = p.worker;
