tool_use_result.originalFile:
// Trace capture: drive the real host (src/host.impl.ts) through the public interface and
// record one NDJSON window per step, observed through run()/worker()/inFlight().
// BFS over the host's reachable observable states; for every state, every action is fired
// once, so every (state, action) pair the spec models has a window from the real code.
// Usage: node spec/capture.ts  → writes spec/traces/*.ndjson

import { mkdirSync, rmSync, writeFileSync } from 'node:fs';
import createHost from '../src/host.impl.ts';
import type { Host } from '../host.ts';

type Step = { action: string; data: Record<string, number> };

const STEPS: Step[] = [
  { action: 'START', data: {} },
  { action: 'CANCEL', data: {} },
  ...['WORK_DONE', 'WORK_FAILED', 'DELIVER_ASSIGN', 'DELIVER_ABORT'].flatMap((action) =>
    [0, 1].map((worker) => ({ action, data: { worker } }))),
  ...[0, 1].map((task) => ({ action: 'DELIVER_REPORT', data: { task } })),
];

async function observe(h: Host) {
  const r = await h.run();
  const s: Record<string, unknown> = {
    status: r.status, task0: r.task0, task1: r.task1,
    w0: (await h.worker('worker0'))!.status, w1: (await h.worker('worker1'))!.status,
    assign0: false, assign1: false, abort0: false, abort1: false, report0: 'none', report1: 'none',
  };
  for (const m of await h.inFlight()) {
    if (m.action === 'Assign') s[`assign${m.to.slice(-1)}`] = true;
    else if (m.action === 'Abort') s[`abort${m.to.slice(-1)}`] = true;
    else if (m.action === 'Report') s[`report${m.data.task}`] = m.data.outcome;
  }
  return s;
}

async function apply(h: Host, { action, data }: Step) {
  const w = `worker${data.worker}`;
  const find = async (pred: (m: { action: string; to: string; from: string }) => boolean) => {
    const m = (await h.inFlight()).find(pred);
    if (m) await h.deliver(m.id);
  };
  switch (action) {
    case 'START': return h.start();
    case 'CANCEL': return h.cancel();
    case 'WORK_DONE': return h.workDone(w);
    case 'WORK_FAILED': return h.workFailed(w);
    case 'DELIVER_ASSIGN': return find((m) => m.action === 'Assign' && m.to === w);
    case 'DELIVER_ABORT': return find((m) => m.action === 'Abort' && m.to === w);
    case 'DELIVER_REPORT': return find((m) => m.action === 'Report' && m.from === `worker${data.task}`);
  }
}

async function replay(path: Step[]) {
  const h = await createHost();
  const windows = [];
  for (const step of path) {
    const pre = await observe(h);
    await apply(h, step);
    windows.push({ pre, action: step.action, data: step.data, post: await observe(h) });
  }
  return { h, windows };
}

const dir = new URL('./traces/', import.meta.url);
rmSync(dir, { recursive: true, force: true });
mkdirSync(dir, { recursive: true });

const seen = new Set<string>();
let frontier: Step[][] = [[]];
let files = 0;
while (frontier.length) {
  const nextFrontier: Step[][] = [];
  for (const path of frontier) {
    const { h } = await replay(path);
    const key = JSON.stringify(await observe(h));
    if (seen.has(key)) continue;
    seen.add(key);
    const n = String(seen.size - 1).padStart(3, '0');
    for (const [k, step] of STEPS.entries()) {
      const { windows } = await replay([...path, step]);
      const body = windows.map((w) => JSON.stringify(w)).join('\n') + '\n';
      writeFileSync(new URL(`s${n}-${String(k).padStart(2, '0')}.ndjson`, dir), body);
      files++;
      nextFrontier.push([...path, step]);
    }
  }
  frontier = nextFrontier;
}
console.log(`${seen.size} states, ${files} trace files`);

