    acceptors: {
      START: (model) => (p, { reject, next, unchanged }) => {
        if (model.status !== 'idle') return reject('already-started');
        next.status = 'running';
        next.task0 = 'assigned';
        next.task1 = 'assigned';
        next.assign0 = true;
        next.assign1 = true;
        unchanged(...others('status', 'task0', 'task1', 'assign0', 'assign1'));
      },
      CANCEL: (model) => (p, { reject, next, unchanged }) => {
        if (model.status !== 'running') return reject('not-running');
        next.status = 'cancelling';
        next.abort0 = model.abort0 + (model.task0 === 'assigned' ? 1 : 0);
        next.abort1 = model.abort1 + (model.task1 === 'assigned' ? 1 : 0);
        unchanged(...others('status', 'abort0', 'abort1'));
      },
      TASK_TIMEOUT: (model) => (p, { reject, next, unchanged }) => {
        const i = p.task;
        if (i !== 0 && i !== 1) return reject('unknown-task');
        if (!live(model.status)) return reject('run-not-live');
        if (model[`task${i}`] !== 'assigned') return reject('task-not-assigned');
        const written = recordTask(model, next, i, 'failed');
        next[`abort${i}`] = model[`abort${i}`] + 1;
        unchanged(...others(...written, `abort${i}`));
