// Runs the model checker on every mutant written by make-mutants.mjs; each should be caught.
import { execFileSync } from 'node:child_process';
import { readdirSync, existsSync } from 'node:fs';

const out = new URL('./out/', import.meta.url);
for (const name of readdirSync(out)) {
  const spec = new URL(`${name}/m.cjs`, out);
  if (!existsSync(spec)) continue;
  let text;
  try {
    text = execFileSync('node', ['tools/polygraph/scripts/check.mjs', '--spec', spec.pathname.replace(/^\/(\w:)/, '$1'),
      '--contract', 'spec/contract.json', '--invariants', 'spec/invariants.mjs'], { encoding: 'utf8', stdio: 'pipe' });
  } catch (e) {
    text = String(e.stdout) + String(e.stderr);
  }
  const broken = [...text.matchAll(/✗ (\S+)/g)].map((m) => m[1]);
  console.log(`${name.padEnd(28)} ${broken.length ? 'caught: ' + broken.join(', ') : 'NOT CAUGHT'}`);
}

