cat >> test/host.test.ts <<'EOF'

test('timeout records a final failure, aborts the worker, and ignores its late report', async () => {
  const h = await createHost();
  assert.equal((await h.taskTimeout(0)).ok, false); // before start
  await h.start();
  await h.deliverAll();
  assert.deepEqual(await h.taskTimeout(0), { ok: true });
  assert.deepEqual(await h.run(), { status: 'running', task0: 'failed', task1: 'assigned', retried0: false, retried1: false });
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 1);
  assert.deepEqual({ from: msgs[0].from, to: msgs[0].to, action: msgs[0].action, data: msgs[0].data },
    { from: 'run', to: 'worker0', action: 'Abort', data: {} });
  assert.equal((await h.taskTimeout(0)).ok, false); // no longer assigned
  assert.equal((await h.taskTimeout(2)).ok, false);
  await h.deliverAll(); // worker0 stops and reports cancelled: ignored
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.equal((await h.run()).task0, 'failed');
  await h.workDone('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'failed', task1: 'completed', retried0: false, retried1: false });
});

test('late completion after a timeout is ignored', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workDone('worker0'); // report in flight
  await h.taskTimeout(0);
  await h.deliverAll();
  assert.equal((await h.run()).task0, 'failed');
});

test('timeout while cancelling can end the run', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.cancel();
  for (const m of (await h.inFlight()).filter((m) => m.to === 'worker0')) await h.deliver(m.id);
  for (const m of (await h.inFlight()).filter((m) => m.action === 'Report')) await h.deliver(m.id);
  assert.deepEqual(await h.taskTimeout(1), { ok: true });
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'cancelled', task1: 'failed', retried0: false, retried1: false });
  assert.equal((await h.taskTimeout(1)).ok, false); // run ended
  await h.deliverAll(); // two Aborts reach worker1: one stops it, the other is ignored
  assert.deepEqual(await h.worker('worker1'), { status: 'idle' });
  assert.deepEqual(await h.inFlight(), []);
});

test('timeout during a retry is final', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker0');
  await h.deliverAll();
  await h.taskTimeout(0);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'running', task0: 'failed', task1: 'assigned', retried0: true, retried1: false });
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
});
EOF
