  await h.start();
  await h.deliverAll();
  await h.workFailed('worker0');
  const [rep] = await h.inFlight();
  await h.deliver(rep.id);
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 1);
  assert.deepEqual({ from: msgs[0].from, to: msgs[0].to, action: msgs[0].action, data: msgs[0].data },
    { from: 'run', to: 'worker0', action: 'Assign', data: {} });
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  await h.deliverAll();
  await h.workDone('worker0', 1);
  await h.workDone('worker1', 1);
  await h.deliverAll();
  assert.deepEqual(await view(h),{ status: 'completed', task0: 'completed', task1: 'completed', retried0: true, retried1: false });
});

test('failure while cancelling is recorded, not retried', async () => {
