  await h.cancel();
  // Deliver only the reports: Aborts reach idle workers later and are ignored.
  for (const m of (await h.inFlight()).filter((m) => m.action === 'Report')) await h.deliver(m.id);
  assert.deepEqual(await view(h),{ status: 'failed', task0: 'failed', task1: 'completed', retried0: false, retried1: false });
  await h.deliverAll();
  assert.deepEqual(await h.inFlight(), []);
});

