import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';
import type { Host } from '../host.ts';

/** run() without processed (checked in items.test.ts). */
const view = async (h: Host) => {
  const { processed, ...rest } = await h.run();
  return rest;
};

test('fresh system is idle', async () => {
  const h = await createHost();
  assert.deepEqual(await view(h),{ status: 'idle', task0: 'idle', task1: 'idle', retried0: false, retried1: false });
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.equal(await h.worker('nope'), null);
  assert.deepEqual(await h.inFlight(), []);
});

test('start sends Assign and refuses a second start', async () => {
  const h = await createHost();
  assert.deepEqual(await h.start(), { ok: true });
  assert.deepEqual(await view(h),{ status: 'running', task0: 'assigned', task1: 'assigned', retried0: false, retried1: false });
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 2);
  for (const m of msgs) {
    assert.equal(m.from, 'run');
    assert.equal(m.action, 'Assign');
    assert.deepEqual(m.data, {});
  }
  assert.equal((await h.start()).ok, false);
  assert.equal((await h.inFlight()).length, 2);
});

test('both complete', async () => {
  const h = await createHost();
  await h.start();
  assert.equal((await h.workDone('worker0', 1)).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  assert.deepEqual(await h.workDone('worker0', 1), { ok: true });
  const [r] = await h.inFlight();
  assert.deepEqual(r.data, { task: 0, outcome: 'completed' });
  assert.equal(r.from, 'worker0');
  assert.equal(r.to, 'run');
  await h.deliverAll();
  assert.equal((await h.run()).status, 'running');
  await h.workDone('worker1', 1);
  await h.deliverAll();
  assert.deepEqual(await view(h),{ status: 'completed', task0: 'completed', task1: 'completed', retried0: false, retried1: false });
});

test('first failure retries; second failure is recorded; failed only once both reported', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker1');
  await h.deliverAll();
  assert.deepEqual(await view(h),{ status: 'running', task0: 'assigned', task1: 'assigned', retried0: false, retried1: true });
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  await h.workFailed('worker1');
  await h.deliverAll();
  assert.deepEqual(await view(h),{ status: 'running', task0: 'assigned', task1: 'failed', retried0: false, retried1: true });
