'use strict';
// SAM v2 strict-profile model of src/core.ts + the network in src/host.impl.ts.
// One step = one command or one message delivery. In-flight messages, per worker:
// - assignN: an Assign in flight (never two: a retry Assign is sent only after the first
//   Report arrived, so the first Assign was consumed);
// - abortN: how many Aborts are in flight (0..2: cancel, then a timeout of the same task);
// - reportN: the outcome of the Report in flight, or 'none' (one per busy period, and a
//   new busy period needs an Assign the run sends only after the Report arrived).
// The invariants check that no Assign or Report is ever sent while one is in flight.

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const INITIAL_STATE = {
  status: 'idle',
  task0: 'idle', task1: 'idle',
  w0: 'idle', w1: 'idle',
  assign0: false, assign1: false,
  abort0: 0, abort1: 0,
  report0: 'none', report1: 'none',
  retried0: false, retried1: false,
};

const KEYS = Object.keys(INITIAL_STATE);
const others = (...written) => KEYS.filter((k) => !written.includes(k));
const W = [{ worker: 0 }, { worker: 1 }];
const T = [{ task: 0 }, { task: 1 }];
const live = (s) => s === 'running' || s === 'cancelling';

/** The run's status after task i is recorded with outcome. */
function statusAfter(model, i, outcome) {
  const tasks = [model.task0, model.task1];
  tasks[i] = outcome;
  const reported = tasks.every((t) => t !== 'assigned');
  if (tasks.every((t) => t === 'completed')) return 'completed';
  if (reported && tasks.includes('failed')) return 'failed';
  if (reported) return 'cancelled';
  return model.status;
}

/** Write task i's final outcome and the run's status; returns the keys written. */
function recordTask(model, next, i, outcome) {
  next[`task${i}`] = outcome;
  const status = statusAfter(model, i, outcome);
  if (status === model.status) return [`task${i}`];
  next.status = status;
  return [`task${i}`, 'status'];
}

function finish(outcome) {
  return (model) => (p, { reject, next, unchanged }) => {
    const i = p.worker;
    if (i !== 0 && i !== 1) return reject('unknown-worker');
    if (model[`w${i}`] !== 'busy') return reject('worker-not-busy');
    next[`w${i}`] = 'idle';
    next[`report${i}`] = outcome;
    unchanged(...others(`w${i}`, `report${i}`));
  };
}

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      status: { type: 'string' },
      task0: { type: 'string' }, task1: { type: 'string' },
      w0: { type: 'string' }, w1: { type: 'string' },
      assign0: { type: 'boolean' }, assign1: { type: 'boolean' },
      abort0: { type: 'number' }, abort1: { type: 'number' },
      report0: { type: 'string' }, report1: { type: 'string' },
      retried0: { type: 'boolean' }, retried1: { type: 'boolean' },
    },
    actions: {
      START: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      CANCEL: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      TASK_TIMEOUT: { action: (data = {}) => ({ ...data }), schema: { task: 'number' }, domain: T },
      WORK_DONE: { action: (data = {}) => ({ ...data }), schema: { worker: 'number' }, domain: W },
      WORK_FAILED: { action: (data = {}) => ({ ...data }), schema: { worker: 'number' }, domain: W },
      DELIVER_ASSIGN: { action: (data = {}) => ({ ...data }), schema: { worker: 'number' }, domain: W },
      DELIVER_ABORT: { action: (data = {}) => ({ ...data }), schema: { worker: 'number' }, domain: W },
      DELIVER_REPORT: { action: (data = {}) => ({ ...data }), schema: { task: 'number' }, domain: T },
    },
    acceptors: {
      START: (model) => (p, { reject, next, unchanged }) => {
        if (model.status !== 'idle') return reject('already-started');
        next.status = 'running';
        next.task0 = 'assigned';
        next.task1 = 'assigned';
        next.assign0 = true;
        next.assign1 = true;
        unchanged(...others('status', 'task0', 'task1', 'assign0', 'assign1'));
      },
      CANCEL: (model) => (p, { reject, next, unchanged }) => {
        if (model.status !== 'running') return reject('not-running');
        next.status = 'cancelling';
        next.abort0 = model.abort0 + (model.task0 === 'assigned' ? 1 : 0);
        next.abort1 = model.abort1 + (model.task1 === 'assigned' ? 1 : 0);
        unchanged(...others('status', 'abort0', 'abort1'));
      },
      TASK_TIMEOUT: (model) => (p, { reject, next, unchanged }) => {
        const i = p.task;
        if (i !== 0 && i !== 1) return reject('unknown-task');
        if (!live(model.status)) return reject('run-not-live');
        if (model[`task${i}`] !== 'assigned') return reject('task-not-assigned');
        const written = recordTask(model, next, i, 'failed');
        next[`abort${i}`] = model[`abort${i}`] + 1;
        unchanged(...others(...written, `abort${i}`));
      },
      WORK_DONE: finish('completed'),
      WORK_FAILED: finish('failed'),
      DELIVER_ASSIGN: (model) => (p, { reject, next, unchanged }) => {
        const i = p.worker;
        if (i !== 0 && i !== 1) return reject('unknown-worker');
        if (!model[`assign${i}`]) return reject('no-assign-in-flight');
        next[`assign${i}`] = false;
        if (model[`w${i}`] === 'idle') {
          next[`w${i}`] = 'busy';
          unchanged(...others(`assign${i}`, `w${i}`));
        } else {
          unchanged(...others(`assign${i}`));
        }
      },
      DELIVER_ABORT: (model) => (p, { reject, next, unchanged }) => {
        const i = p.worker;
        if (i !== 0 && i !== 1) return reject('unknown-worker');
        if (model[`abort${i}`] === 0) return reject('no-abort-in-flight');
        next[`abort${i}`] = model[`abort${i}`] - 1;
        if (model[`w${i}`] === 'busy') {
          next[`w${i}`] = 'idle';
          next[`report${i}`] = 'cancelled';
          unchanged(...others(`abort${i}`, `w${i}`, `report${i}`));
        } else {
          unchanged(...others(`abort${i}`));
        }
      },
      DELIVER_REPORT: (model) => (p, { reject, next, unchanged }) => {
        const i = p.task;
        if (i !== 0 && i !== 1) return reject('unknown-task');
        const outcome = model[`report${i}`];
        if (outcome === 'none') return reject('no-report-in-flight');
        next[`report${i}`] = 'none';
        if (!live(model.status) || model[`task${i}`] !== 'assigned') {
          unchanged(...others(`report${i}`));
          return;
        }
        if (outcome === 'failed' && model.status === 'running' && !model[`retried${i}`]) {
          next[`retried${i}`] = true;
          next[`assign${i}`] = true;
          unchanged(...others(`report${i}`, `retried${i}`, `assign${i}`));
          return;
        }
        const written = recordTask(model, next, i, outcome);
        unchanged(...others(`report${i}`, ...written));
      },
    },
    reactors: [],
  },
});

const { intents } = control;

const getState = () => instance({}).getState();
const setState = (snapshot) => { instance({}).setState(snapshot); };
const init = () => { setState(INITIAL_STATE); };

const actions = {
  START: (data = {}) => intents.START(data),
  CANCEL: (data = {}) => intents.CANCEL(data),
  TASK_TIMEOUT: (data = {}) => intents.TASK_TIMEOUT(data),
  WORK_DONE: (data = {}) => intents.WORK_DONE(data),
  WORK_FAILED: (data = {}) => intents.WORK_FAILED(data),
  DELIVER_ASSIGN: (data = {}) => intents.DELIVER_ASSIGN(data),
  DELIVER_ABORT: (data = {}) => intents.DELIVER_ABORT(data),
  DELIVER_REPORT: (data = {}) => intents.DELIVER_REPORT(data),
};

module.exports = { instance, init, actions, getState, setState };

