// Rules the brief requires of the run and its workers, whatever order messages arrive in.

const TERMINAL = ['completed', 'failed', 'cancelled'];
const REPORTED = ['completed', 'failed', 'cancelled'];
const tasks = (s) => [s.task0, s.task1];
const nothingInFlight = (s) =>
  !s.assign0 && !s.assign1 && !s.abort0 && !s.abort1 && s.report0 === 'none' && s.report1 === 'none';

export const stateInvariants = [
  {
    name: 'completed-only-when-both-completed',
    pred: (s) => s.status !== 'completed' || tasks(s).every((t) => t === 'completed'),
  },
  {
    name: 'ends-only-when-both-reported',
    pred: (s) => !TERMINAL.includes(s.status) || tasks(s).every((t) => REPORTED.includes(t)),
  },
  {
    name: 'failed-means-a-task-failed',
    pred: (s) => s.status !== 'failed' || tasks(s).includes('failed'),
  },
  {
    name: 'cancelled-means-none-failed-and-not-all-completed',
    pred: (s) =>
      s.status !== 'cancelled' ||
      (!tasks(s).includes('failed') && !tasks(s).every((t) => t === 'completed')),
  },
  {
    name: 'both-reported-means-ended',
    pred: (s) => !tasks(s).every((t) => REPORTED.includes(t)) || TERMINAL.includes(s.status),
  },
  {
    name: 'idle-run-has-idle-tasks',
    pred: (s) => (s.status === 'idle') === (s.task0 === 'idle' && s.task1 === 'idle'),
  },
  {
    name: 'cancelled-task-only-after-cancel',
    pred: (s) => !tasks(s).includes('cancelled') || s.status !== 'running',
  },
  {
    // A timed-out task's worker may still be busy: its Abort is in flight, or it overtook the
    // Assign and was ignored. Its later report is ignored. No other finished task has a busy worker.
    name: 'busy-worker-has-assigned-or-timed-out-task',
    pred: (s) => [0, 1].every((i) => s[`w${i}`] !== 'busy' || ['assigned', 'failed'].includes(s[`task${i}`])),
  },
  {
    name: 'at-most-two-aborts-in-flight',
    pred: (s) => s.abort0 <= 2 && s.abort1 <= 2,
  },
  {
    name: 'assign-reaches-only-idle-worker',
    pred: (s) => [0, 1].every((i) => !s[`assign${i}`] || s[`w${i}`] === 'idle'),
  },
  {
    name: 'retried-only-after-start',
    pred: (s) => s.status !== 'idle' || (!s.retried0 && !s.retried1),
  },
  {
    name: 'quiescent-started-run-has-ended',
    pred: (s) =>
      s.status === 'idle' || !nothingInFlight(s) || s.w0 === 'busy' || s.w1 === 'busy' ||
      TERMINAL.includes(s.status),
  },
];

export const transitionInvariants = [
  {
    name: 'ended-run-never-changes',
    pred: (pre, a, d, post) =>
      !TERMINAL.includes(pre.status) || (post.status === pre.status && post.task0 === pre.task0 && post.task1 === pre.task1),
  },
  {
    name: 'reported-task-never-changes',
    pred: (pre, a, d, post) => [0, 1].every((i) => !REPORTED.includes(pre[`task${i}`]) || post[`task${i}`] === pre[`task${i}`]),
  },
  {
    name: 'abort-only-for-assigned-task',
    pred: (pre, a, d, post) => [0, 1].every((i) => post[`abort${i}`] <= pre[`abort${i}`] || pre[`task${i}`] === 'assigned'),
  },
  {
    name: 'timeout-is-a-final-failure-with-abort',
    pred: (pre, a, d, post) => {
      if (a !== 'TASK_TIMEOUT') return true;
      const i = d.task;
      const applies = ['running', 'cancelling'].includes(pre.status) && pre[`task${i}`] === 'assigned';
      if (!applies) return JSON.stringify(pre) === JSON.stringify(post);
      return post[`task${i}`] === 'failed' && post[`abort${i}`] === pre[`abort${i}`] + 1 &&
        post[`retried${i}`] === pre[`retried${i}`] && post[`assign${i}`] === pre[`assign${i}`];
    },
  },
  {
    name: 'retried-never-reset',
    pred: (pre, a, d, post) => [0, 1].every((i) => !pre[`retried${i}`] || post[`retried${i}`]),
  },
  {
    name: 'first-failure-while-running-is-retried',
    pred: (pre, a, d, post) => {
      const i = d.task;
      if (a !== 'DELIVER_REPORT' || pre[`report${i}`] !== 'failed') return true;
      if (pre.status !== 'running' || pre[`task${i}`] !== 'assigned' || pre[`retried${i}`]) return true;
      return post[`task${i}`] === 'assigned' && post[`retried${i}`] && post[`assign${i}`] && post.status === pre.status;
    },
  },
  {
    name: 'second-failure-or-failure-while-cancelling-is-recorded',
    pred: (pre, a, d, post) => {
      const i = d.task;
      if (a !== 'DELIVER_REPORT' || pre[`report${i}`] !== 'failed' || pre[`task${i}`] !== 'assigned') return true;
      if (pre.status === 'cancelling' || (pre.status === 'running' && pre[`retried${i}`])) {
        return post[`task${i}`] === 'failed' && post[`retried${i}`] === pre[`retried${i}`] && !post[`assign${i}`];
      }
      return true;
    },
  },
  {
    name: 'task-fails-only-after-retry-while-cancelling-or-by-timeout',
    pred: (pre, a, d, post) =>
      [0, 1].every((i) => pre[`task${i}`] === post[`task${i}`] || post[`task${i}`] !== 'failed' ||
        pre[`retried${i}`] || pre.status === 'cancelling' || a === 'TASK_TIMEOUT'),
  },
  {
    name: 'no-message-overwritten',
    pred: (pre, a, d, post) =>
      [0, 1].every((i) =>
        (pre[`report${i}`] === 'none' || post[`report${i}`] === pre[`report${i}`] || post[`report${i}`] === 'none') &&
        (!pre[`assign${i}`] || a !== 'START' || post.status === pre.status) &&
